public class InnerEventSourceEventSourceConfigurationFactory(Action<Humidifier.EventsV2.EventSourceTypes.EventSourceConfiguration> factoryAction = null) : SubResourceFactory<Humidifier.EventsV2.EventSourceTypes.EventSourceConfiguration>
{

    internal InnerEventSourceAwsServiceEventsConfigurationFactory AwsServiceEventsConfigurationFactory { get; set; }

    internal InnerEventSourcePartnerEventsConfigurationFactory PartnerEventsConfigurationFactory { get; set; }

    protected override Humidifier.EventsV2.EventSourceTypes.EventSourceConfiguration Create()
    {
        var eventSourceConfigurationResult = CreateEventSourceConfiguration();
        factoryAction?.Invoke(eventSourceConfigurationResult);

        return eventSourceConfigurationResult;
    }

    private Humidifier.EventsV2.EventSourceTypes.EventSourceConfiguration CreateEventSourceConfiguration()
    {
        var eventSourceConfigurationResult = new Humidifier.EventsV2.EventSourceTypes.EventSourceConfiguration();

        return eventSourceConfigurationResult;
    }
    public override void CreateChildren(Humidifier.EventsV2.EventSourceTypes.EventSourceConfiguration result)
    {
        base.CreateChildren(result);

        result.AwsServiceEventsConfiguration ??= AwsServiceEventsConfigurationFactory?.Build();
        result.PartnerEventsConfiguration ??= PartnerEventsConfigurationFactory?.Build();
    }

} // End Of Class

